// positive integer, rejecting signs, whitespace, fractions and overflow.
func parsePositiveDecimal(raw string) (int, bool) {
	if raw == "" {
		return 0, false
	}
	for _, digit := range raw {
		if digit < '0' || digit > '9' {
			return 0, false
		}
	}
	value, err := strconv.Atoi(raw)
	if err != nil || value < 1 {
		return 0, false
	}
	return value, true
}

