var Statuses = []Status{
	StatusOpen,
	StatusInProgress,
	StatusFixed,
	StatusWontFix,
	StatusAccepted,
}

// ValidSeverity reports whether severity is one of the published values.
func ValidSeverity(severity Severity) bool {
	for _, candidate := range Severities {
		if severity == candidate {
