	})
	registerRangeVulnerability(t, router, "CVE-2024-0003", "libxml2", []map[string]any{
		{"lower": "3.0", "lower_include": true, "upper": "4.0", "upper_include": true},
	})
	registerRangeVulnerability(t, router, "CVE-2024-0004", "LIBXML2", []map[string]any{
		{"lower": "2.0", "lower_include": true, "upper": "2.9", "upper_include": true},
	})

	recorder := doJSON(t, router, http.MethodPost, "/vulnerabilities/range-match", map[string]any{
		"queries": []map[string]any{
			{"component": "libxml2", "lower": "2.0", "upper": "2.0", "lower_include": true, "upper_include": true},
			{"component": "unknown-lib", "lower": "1.0", "upper": "2.0", "lower_include": true, "upper_include": true},
			{"component": "libxml2", "lower": "2.9", "upper": "3.1", "lower_include": false, "upper_include": true},
			{"component": "LIBXML2", "lower": "2.9", "upper": "3.0", "lower_include": true, "upper_include": true},
		},
	})
	if recorder.Code != http.StatusOK {
		t.Fatalf("status = %d body = %s", recorder.Code, recorder.Body.String())
	}
	var response struct {
		Results []struct {
			Component    string `json:"component"`
			Lower        string `json:"lower"`
			Upper        string `json:"upper"`
			LowerInclude bool   `json:"lower_include"`
			UpperInclude bool   `json:"upper_include"`
			Vulns        []struct {
				ID            string           `json:"id"`
				Component     string           `json:"component"`
				MatchedRanges []map[string]any `json:"matched_ranges"`
				Severity      string           `json:"severity"`
				FixedVersion  string           `json:"fixed_version"`
				Status        string           `json:"status"`
			} `json:"vulnerabilities"`
		} `json:"results"`
	}
	if err := json.Unmarshal(recorder.Body.Bytes(), &response); err != nil {
		t.Fatalf("unmarshal: %v body=%s", err, recorder.Body.String())
	}
	if len(response.Results) != 4 {
		t.Fatalf("results = %d, want 4", len(response.Results))
	}

	first := response.Results[0]
	if first.Component != "libxml2" || first.Lower != "2.0" || first.Upper != "2.0" ||
		!first.LowerInclude || !first.UpperInclude {
		t.Fatalf("query not echoed: %+v", first)
	}
	if len(first.Vulns) != 2 {
		t.Fatalf("first hits = %d, want 2 (both include 2.0)", len(first.Vulns))
	}
	if first.Vulns[0].ID != "CVE-2024-0001" || first.Vulns[1].ID != "CVE-2024-0002" {
		t.Fatalf("vulnerabilities not id-sorted: %+v", first.Vulns)
	}
	for _, hit := range first.Vulns {
		if hit.Component != "libxml2" || hit.Severity != "high" ||
			hit.FixedVersion != "2.10.0" || hit.Status != "open" {
			t.Fatalf("projection fields wrong: %+v", hit)
		}
		if len(hit.MatchedRanges) != 1 {
			t.Fatalf("matched_ranges = %v, want one", hit.MatchedRanges)
		}
	}

	if len(response.Results[1].Vulns) != 0 {
		t.Fatalf("unknown component must have empty hits: %+v", response.Results[1])
	}

	third := response.Results[2]
	if len(third.Vulns) != 1 || third.Vulns[0].ID != "CVE-2024-0003" {
		t.Fatalf("touching-exclusive query must only hit the inclusive range: %+v", third)
	}

	fourth := response.Results[3]
	if fourth.Component != "LIBXML2" || len(fourth.Vulns) != 1 ||
