func TestRangeMatchKeepsOnlyIntersectingRanges(t *testing.T) {
	router := newTestRouter(t)
	registerRangeVulnerability(t, router, "CVE-2024-0001", "libxml2", []map[string]any{
		{"lower": "1.0", "lower_include": true, "upper": "2.0", "upper_include": true},
		{"upper": "0.9", "upper_include": true},
		{"lower": "5.0", "lower_include": false},
	})

	recorder := doJSON(t, router, http.MethodPost, "/vulnerabilities/range-match", map[string]any{
		"queries": []map[string]any{
			{"component": "libxml2", "lower": "3.0", "upper": "5.0", "lower_include": true, "upper_include": true},
		},
	})
	if recorder.Code != http.StatusOK {
		t.Fatalf("status = %d body = %s", recorder.Code, recorder.Body.String())
	}
	var response struct {
		Results []struct {
			Vulns []struct {
				MatchedRanges []map[string]any `json:"matched_ranges"`
			} `json:"vulnerabilities"`
		} `json:"results"`
	}
	if err := json.Unmarshal(recorder.Body.Bytes(), &response); err != nil {
		t.Fatalf("unmarshal: %v", err)
	}
	if len(response.Results[0].Vulns) != 1 || len(response.Results[0].Vulns[0].MatchedRanges) != 1 {
		t.Fatalf("want only the open-upper? no: only the 5.0-exclusive range, got %+v", response.Results)
	}
	matched := response.Results[0].Vulns[0].MatchedRanges[0]
	if matched["lower"] != "5.0" || matched["lower_include"] != false {
		t.Fatalf("wrong range retained: %v", matched)
	}
}

